head.script:
scwin.screenId = "jldods29000";

///////// 1. 변수 및 선언 영역 /////////

scwin.mainIndex = "";


///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_pageCount", fn: function(){ return ((dma_page.get("pageCount") ?? (() => { throw new Error("unresolved:" + "page.pageCount"); })())!=0); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String(dma_page.get("total")) + "건 [0" + String(dma_sprtroomForm.get("pageIndex")) + "/" + String(dma_page.get("pageCount")) + " 페이지]"; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        const contnId = (String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "contnId" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("contnId"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "contnId" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("contnId")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "contnId" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("contnId"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "contnId" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("contnId")))));
        const index = (String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "index" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("index"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "index" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("index")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "index" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("index"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "index" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("index")))));
        if (contnId.length > 0) {
            scwin.detail(contnId, index, 'init');
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods29000.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldods29000: 진입 키 faq 는 알지만 그 URL 을 쓰는 tx 가 화면에 없다(URL 을 지어내지 않는다) · 자기 목록 tx 0


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldods29000.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.input_21_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.input_21_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin input_21_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.search(1)
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods29000.input_21_onclick' }); }
};

/**
 * @event
 * @name scwin.slc_pageSize_onchange
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.slc_pageSize_onchange = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin slc_pageSize_onchange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.search(1);
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods29000.slc_pageSize_onchange' }); }
};

/**
 * @event
 * @name scwin.noticeTable_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.noticeTable_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_faqList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_faqList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (typeof scwin.detail === 'function') { scwin.detail(r["sprtRoomNo"], r["index"]); } else { console.error('[sdd] 행 동작 미정의: scwin.detail (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.detail'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'noticeTable.oncellclick' });
    }
};


///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @event
 * @name scwin.__on_enter_1_ipt_keyword
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.__on_enter_1_ipt_keyword = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin __on_enter_1_ipt_keyword — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if(($c.util.getKeyCode(ev))==13){ scwin.search() }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods29000.__on_enter_1_ipt_keyword' }); }
};

/**
 * @method
 * @name scwin.detail
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_sprtRoomNo index init
 * @returns
 * @hidden N
*/
scwin.detail = function (ipt_sprtRoomNo, index, init) {
    /* sdd-asis-lifecycle:begin fn_detail — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $('#ipt_sprtRoomNo', $('#searchForm')).val(ipt_sprtRoomNo);
    $('#ipt_SCREN_ID', $('#searchForm')).val("/jldods29010/jldods29010.xml");
    $('#ipt_method', $('#searchForm')).val("readFaqDetail");
    $('#searchForm').submit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_pageIndex
 * @returns
 * @hidden N
*/
scwin.search = function (ipt_pageIndex) {
    /* sdd-asis-lifecycle:begin fn_search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (ipt_pageIndex) {
        $('#ipt_pageIndex', $('#searchForm')).val(ipt_pageIndex);
    }
    blockLoading();
    $('#ipt_SCREN_ID', $('#searchForm')).val("/jldods29000/jldods29000.xml");
    $('#ipt_method', $('#searchForm')).val("readFaqList");
    $('#searchForm').submit();
    /* sdd-asis-lifecycle:end */
};



/**
 * @event
 * @name scwin.krxpage_pagenavigator_55_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param index
 * @returns
 * @hidden N
*/
scwin.krxpage_pagenavigator_55_onclick = function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; scwin.search(); };
